node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createFeed } from './src/index.mjs';

const feed = createFeed();
const original = { nested: { value: 1 }, list: [1], map: new Map([['x', { value: 2 }]]) };
const committed = feed.publishBatch('one', [{ type: 'created', payload: original }]);
original.nested.value = 99;
assert.equal(feed.history('one')[0].payload.nested.value, 1);
committed[0].payload.nested.value = 88;
assert.equal(feed.history('one')[0].payload.nested.value, 1);
const history = feed.history('one');
history[0].payload.map.get('x').value = 77;
assert.equal(feed.history('one')[0].payload.map.get('x').value, 2);

const deliveries = [];
feed.subscribe('one', 0, record => {
  deliveries.push(record);
  record.payload.nested.value = 42;
});
const results = feed.publishBatch('one', [{ type: 'updated', payload: { nested: { value: 3 } } }]);
assert.equal(results[0].payload.nested.value, 3);
assert.equal(deliveries[1].payload.nested.value, 42);
assert.equal(feed.history('one')[1].payload.nested.value, 3);

assert.throws(() => feed.publishBatch('two', [
  { type: 'ok', payload: { value: 1 } },
  { type: '', payload: {} },
]));
assert.deepEqual(feed.history('two'), []);
const next = feed.publishBatch('two', [{ type: 'ok', payload: { value: 2 } }]);
assert.equal(next[0].sequence, 3);
assert.deepEqual(feed.history('two').map(record => record.sequence), [3]);
console.log('contract checks passed');
EOF

