import { validateEvent } from './validation.mjs';
import { makeRecord } from './record.mjs';
export function appendBatch(state, tenant, events) {
  let sequence = state.sequence;
  const records = [];
  for (const event of events) {
    const validatedEvent = validateEvent(event);
    records.push(makeRecord(tenant, validatedEvent, ++sequence));
  }
  const committedRecords = state.records.concat(records);
  state.records = committedRecords;
  state.sequence = sequence;
  return records;
}

